"""Render the discussion plan and its maintained notation registry; no inference."""
from html import escape as e
import hashlib,json
from pathlib import Path
from build_project_progress import document,bullets,status_list,STATUS_JS
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/what-to-think'
def read(name):return json.loads((D/name).read_text())
def m(tex):return r'\('+e(tex)+r'\)'
def eq(tex):return '<div class="equation">'+r'\['+e(tex)+r'\]'+'</div>'
MATH=r'''<script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},svg:{fontCache:'global'}};</script><script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js"></script>'''
CSS='''.equation{max-width:100%;overflow-x:auto;margin:1rem 0;padding:1rem;border-radius:9px;background:var(--surface-2)}.equation mjx-container[display="true"]{margin:0!important}mjx-container{max-width:100%}.plan-list li{margin:.65rem 0}.plan-note{border-left:4px solid var(--accent);padding:.7rem 1rem;background:var(--accent-soft)}.chunk-demo{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.5rem;margin:1rem 0}.chunk-demo>div{padding:.8rem;border:1px solid var(--border);border-radius:8px}.plan-table{font-size:.92rem}.plan-table th{min-width:7rem}.plan-table td{overflow-wrap:anywhere}.plan-table mjx-container{font-size:95%!important}.notation-table td:first-child{min-width:12rem}.token-legend{font-size:.9rem;color:var(--muted)}@media(max-width:700px){.chunk-demo{grid-template-columns:1fr}.plan-table{font-size:.88rem}}'''
class Tables:
 def __init__(self):self.n=0
 def __call__(self,caption,headers,rows,extra=''):
  self.n+=1;key='plan-table-'+str(self.n)
  return '<p class="asset-label table-caption" id="'+key+'">Table '+str(self.n)+'. '+e(caption)+'<span class="table-scroll-hint">Scroll sideways on a narrow screen.</span></p><div class="table-wrap" tabindex="0" role="region" aria-labelledby="'+key+'"><table class="plan-table '+extra+'" aria-labelledby="'+key+'"><thead><tr>'+''.join('<th scope="col">'+e(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def ul(items):return '<ul class="plan-list">'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul>'
def finish(name,title,body):
 text=document(name,title,'todo',body,STATUS_JS)
 text=text.replace('</head>','<style>'+CSS+'</style>'+MATH+'</head>')
 (ROOT/name).write_text(text)

LABELS={'complete':'Done','pending':'To do','planned':'Later','partial':'Partly complete'}
def checklist(progress):
 return status_list(progress['tasks'],LABELS)
def intro_sections(p,progress):
 term=p['terminology'];gate=p['evaluation_gate']
 body='<section class="section" id="terminology"><h2>Amortized thinking</h2>'+bullets([dict(text=term['definition']),dict(text=term['cost_note']),dict(text=term['scope_note'])])+'<p>This name fits the project: earlier work may support later requests. <a href="'+term['source']+'">Chronological Thinking</a> also describes reasoning during listening as amortized; our proposed experiments still need to test the benefit.</p></section>'
 body+='<section class="section" id="checklist"><h2>Experiment checklist</h2><p>Checked means the work is done; unchecked means it remains to do or is planned for later. These states come from the <a href="research/what-to-think/execution-progress.json">same progress record</a> as the project TODO and experiment progress page.</p>'+checklist(progress)+'</section>'
 body+='<section class="section" id="evaluation-first"><h2>First validate the evaluation pipeline with S1</h2><p class="plan-note"><strong>Required before broader experiments:</strong> '+e(gate['scope'])+'</p><p>Start with '+e(gate['first_model'])+'.</p>'+ul(gate['checks'])+'<p><strong>Pass rule:</strong> '+e(gate['pass_rule'])+'</p><p>'+e(gate['next'])+'</p><p><strong>Current status:</strong> not implemented or validated in this turn; no new S1 or S2 inference has run.</p></section>'
 body+='<section class="section" id="progress-updates"><h2>Keep progress and examples in sync</h2>'+ul(p['progress_reporting']['requirements'])+'<p>'+e(p['progress_reporting']['distinction'])+'</p><p><a href="study-progress.html">Open the current progress page</a>; it is a dated plan snapshot until run-time reporting is implemented.</p></section>'
 return body

def build_progress(progress,p):
 # This is an earlier, real model output used only to illustrate the report format.
 # It is not part of the new 105-question evaluation or evidence that the evaluator passes.
 source=json.loads((ROOT/'research/current-s1.json').read_text())['traces']['S1-01'];meta=source['metadata']
 output=''.join(x.get('details',{}).get('tts','') for x in source['events'] if x.get('lane')=='thinker')
 speech=next(x for x in source['media'] if x.get('automatic_transcript'))
 body='<header class="hero"><h1>Experiment progress</h1></header><section class="section" id="summary">'+bullets([dict(text='The new 105-question evaluation has not started; this is a plan snapshot dated '+progress.get('updated_at',progress['updated'])+'.'),dict(text='The S1 evaluation pipeline must be implemented and validated before broader experiments.'),dict(text='No new responses are scored, and the earlier example below is excluded from the planned results.')])+'<p><a href="what-to-think.html">Experiment plan</a> · <a href="todo.html">Project TODO</a> · <a href="daily-log.html">Daily log</a></p></section>'
 t=Tables();body+='<section class="section" id="counts"><h2>Current study counts</h2>'+t('Planned work and completed work are separate; unmeasured accuracy is unavailable.',['Item','Current status'],[['Final responses planned',str(progress['planned_final_answers'])+' across '+str(progress['planned_cells'])+' conditions, each with '+str(progress['planned_questions_per_condition'])+' questions'],['Attempted / completed / reviewed',' / '.join(str(progress[k]) for k in ['attempted','completed_outputs','reviewed_outputs'])],['Final accuracy','Not measured'],['Active job','None for this plan update'],['Evaluation protocol','Not validated'],['Run-time progress updater','Specified; not implemented']])+'</section><section class="section" id="checklist"><h2>Shared checklist</h2>'+checklist(progress)+'</section>'
 body+='<section class="section" id="examples"><h2>Examples</h2><p><strong>Current-study pilot examples:</strong> none yet; an inspected end-to-end S1 example is required before the evaluation gate can pass.</p><details id="earlier-example"><summary>Earlier real S1 output: an example of what an evaluation record should show</summary><p>This saved DuplexOmni S1 output is from job '+e(meta['job_id'])+' on 8 October 2026, not the new meeting-history evaluation. The model and independent transcript are copied from the existing record; the fact check below is an editorial illustration, not output from the proposed evaluator.</p>'+t('Earlier S1-01 example, excluded from all new study counts.',['Field','Saved value or illustrative check'],[['Actual request',e(meta['initial_request'])],['Required fact for this simple question','The sky is blue on a clear day.'],['Native model answer text',e(output)],['Independent output-audio transcript',e(speech['automatic_transcript'])],['Illustrative fact check','The answer includes blue and addresses the clear-day question; it satisfies this simple required fact.'],['Scope of this check','This illustrates answer extraction and a factual judgment; it does not validate long history, the new evaluator or all 105 references.'],['Native thinking tokens','N/A for this S1 output; no separate native thinking channel is exposed.'],['Historical job resources','1 A100-SXM4 80 GB; all S1 components on GPU 0, no S2, maximum 1 active GPU for that job.']])+'<p><a href="experiments/single-request.html">Play the saved request and actual output audio</a> · <a href="research/current-s1.json">Recorded response fields and independent transcript</a></p></details></section>'
 body+='<section class="section" id="reporting"><h2>During execution</h2>'+ul(p['progress_reporting']['requirements'])+'<p>'+e(p['progress_reporting']['distinction'])+'</p><p>This page currently shows a published snapshot; the planned 30-second run-time updates are not active. This report edit uses 0 GPUs, with no GPU roles, shared components or dependencies; maximum active GPUs is 0.</p></section>'
 finish('study-progress.html','Experiment progress',body)

def main():
 manifest={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in D.iterdir() if f.is_file() and f.name!='manifest.json'}
 (D/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
 progress=read('execution-progress.json');p=read('plan.json');registry=read('models.json');notation=read('notation.json');prompts=read('prompts.json');results=read('results-template.json');lit=read('literature.json');t=Tables()
 body='<header class="hero"><span class="eyebrow">Plan for discussion · no new inference</span><h1>What to think</h1></header><section class="section" id="summary"><h2>The plan in six sentences</h2><p class="definition">S1 is the duplex speech model; S2 is the reasoning model that can support it.</p>'+bullets([dict(text=x) for x in p['summary']])+'<p><a href="todo.html">Project TODO</a> · <a href="notation.html">Notation table</a> · <a href="daily-log.html">Daily log</a> · <a href="study-progress.html">Experiment progress</a> · <a href="#results">Empty results tables</a></p></section>'
 body+=intro_sections(p,progress)
 body+='<section class="section" id="scope"><h2>Evaluation set and reference answers</h2><p>Use all 105 distinct questions: 93 AMI questions over 24 meetings and 12 earnings-call questions over two calls. Every question has an existing recording and a draft reference answer. The earlier twenty-question review is starting evidence; this plan does not certify all 105 references. Keep alternatives under their original question.</p>'+ul(p['gold_steps'])+'<p><strong>Gate before evaluation:</strong> freeze 105 verified text answers and required-fact checklists. Reference-answer speech remains deferred. Prompt and chunk tuning use additional meetings outside the existing evaluation bank.</p><p><a href="research/what-to-think/answer-validation-template.json">All 105 reference-audit records</a> · <a href="experiments/question-overview.html">Existing question statistics</a></p></section>'
 body+='<section class="section" id="chunking"><h2>Use shared chunks with enough speech</h2><p>Small S1 audio frames stay model-specific. The larger amortized thinking chunks are shared across text and audio conditions; voice activity detection (VAD) marks speech and pauses.</p>'+ul([p['chunking'][key] for key in ['rule','fillers','cap_rule','low_activity','request','common_schedule','causality','same_content']])
 body+='<figure><div class="chunk-demo"><div>0–3 s: “um”</div><div>3–8 s: acknowledgement</div><div>8–26 s: promise and constraint</div><div>26–26.5 s: observed pause</div></div><figcaption>Figure 1. Illustrative grouping: these small units become one useful chunk, rather than four separate earlier model calls; this is not a measured source alignment.</figcaption></figure><p>'+e(p['chunking']['development'])+' '+e(p['chunking']['not_when_study'])+'</p></section>'
 body+='<section class="section" id="notation"><h2>Separate time, instructions and results</h2><p>'+e(notation['convention'])+' GT means the manual ground-truth transcript; ASR means automatic speech recognition. The actual user question is part of the input at request time; it is hidden from all earlier earlier model calls.</p>'
 core_ids=['case_count','case','model','parameters','probability','tool','goal','selected_goal','time','onset','request_end','waveform','frame_count','frame_index','frame','chunk_count','chunk_index','chunk_end','chunk','spoken_request','text_request','gt','asr','history','chunk_history','goals','answer_instruction','earlier_thinking','notes','result','previous_results','request_results','request_thinking','answer','output_audio','response']
 by_id={x['id']:x for x in notation['symbols']};short=[by_id[key] for key in core_ids]
 body+='<p><strong>Example:</strong> '+m('e=17')+' means the seventeenth question; '+m('m')+' could identify Qwen3-30B Instruct; '+m('i=3')+' is its third larger thinking chunk, while '+m('j')+' counts the model’s much smaller input frames.</p>'
 body+=t('Symbols used in the experiment formulas; e always identifies a question and m always identifies a model.',['Symbol','Meaning'],[[m(x['tex']),e(x['name']+'. '+x['definition'])] for x in short])
 body+='<p>The original use of '+m('z')+' for both an index and a result is resolved: '+m('i')+' is the integer index and '+m('z_i')+' is the generated saved result. The generic answer-format instruction '+m(r'q^{\mathrm{ans}}')+' is shared across conditions and omitted from the formulas below.</p><p><a href="notation.html">Open the full notation table</a> · <a href="research/what-to-think/notation.json">Machine-readable registry</a></p></section>'
 body+='<section class="section" id="conditions"><h2>The experiment families</h2><p>A reactive S2 baseline runs only after the actual request. An amortized thinking variant has two parts: updates while listening and a final request-time answer.</p>'
 body+=eq(r'z_i\sim p_{\theta_m}(z_i\mid D_{e,i},Z_{<i},Q_{\le i}^{(g)})')
 body+='<p>Apply this update only to chunks ending before the request: '+m('t_i<S_e')+'. Here '+m('D_{e,i}')+' is the available GT transcript, generated transcript or audio prefix. Collect only those earlier results in '+m('Z_e^{-}')+'; the unfinished meeting tail and complete request are added to the final input.</p>'
 body+=t('Core families, each evaluated on the same 105 questions. T3 and T4 repeat for each transcript tool; the common final-answer instruction is suppressed.',['ID','Input and earlier work','Request-time distribution','Output'],[
 ['S1','Native audio only; S2 disabled.',m(r'p_{\theta_m}(R_e\mid x^{(m)}_{1:J_{m,e}})'),'Speech and native text where available.'],
 ['T1','GT transcript; no earlier earlier model calls.',m(r'p_{\theta_m}(h_e,r_e\mid Y_{\le T_e})'),'Native thinking, if exposed, and answer text.'],
 ['T2','GT transcript plus earlier results and chosen thinking goals.',m(r'p_{\theta_m}(h_e,r_e\mid Y_{\le T_e},Z_e^{-},Q^{(g)})'),'Same output fields as T1.'],
 ['T3(v)','Generated speaker-attributed transcript; no earlier earlier model calls.',m(r'p_{\theta_m}(h_e,r_e\mid\widehat Y^{(v)}_{\le T_e})'),'Same output fields as T1.'],
 ['T4(v)','Generated transcript plus earlier results and chosen thinking goals.',m(r'p_{\theta_m}(h_e,r_e\mid\widehat Y^{(v)}_{\le T_e},Z_e^{-},Q^{(g)})'),'Same output fields as T1.'],
 ['A1','Audio prefix with the spoken request; no earlier earlier model calls.',m(r'p_{\theta_m}(h_e,r_e\mid A_{e,\le T_e})'),'Audio-grounded thinking and text answer.'],
 ['A2','Audio prefix plus earlier earlier results and chosen goals.',m(r'p_{\theta_m}(h_e,r_e\mid A_{e,\le T_e},Z_e^{-},Q^{(g)})'),'Same output fields as A1.']])
 body+='<p>For T2/T4 the update equation uses the matching transcript prefix; for A2 it uses the matching audio prefix. For a model without a native thinking channel, the output is only '+m('r_e')+'; omit '+m('h_e')+' from the joint expression. These equations describe inference behavior, not a new training loss or a measured log-likelihood. Supplying earlier results does not make them correct by definition.</p>'+ul(p['protocol'])+'</section>'
 body+='<section class="section" id="models"><h2>Model and transcript-tool candidates</h2><p>Checked against primary model cards and papers on 27 October 2026. These are local candidates for qualification, not a claim of new performance on this evaluation set; revisions, modes, precision and decoding must be frozen before runs.</p>'
 body+=t('Primary model candidates; text-only describes the experimental input, even when a checkpoint can accept other modalities.',['Group','Model','Why include it?','Native thinking status'],[[e(x['group']),'<a href="'+e(x['source'],quote=True)+'">'+e(x['name'])+'</a>',e(x['reason']),e(x['thinking'].replace('_',' '))] for x in registry['models']])
 body+=t('Two generated-transcript pipelines; speaker clusters and their revisions remain tool-generated.',['ID','Pipeline','Use and causal rule'],[[x['id'],'<a href="'+x['sources'][0]+'">'+e(x['name'])+'</a> · <a href="'+x['sources'][1]+'">diarizer</a>',e(x['reason']+' '+x['causality'])] for x in registry['transcript_tools']])
 body+='<p>Nemotron 3 supports eight speakers; the older four-speaker Sortformer is not the default for earnings calls. Prefix-only pyannote/WhisperX recomputation is an offline content condition, not evidence of real-time streaming. Never attach GT names to generated speaker clusters in model inputs.</p><details><summary>Newer or alternative models considered</summary>'+ul([x['name']+': '+x['decision'] for x in registry['reviewed_reserves']])+'<p>Gemma 4 31B is retained for text; the audio-capable 12B card limits audio to thirty seconds, so it is not substituted into a full-history audio comparison.</p></details></section>'
 body+='<section class="section" id="prompts"><h2>Select the thinking goals on development data</h2><p>The best prompt is not known yet. Start with the following source-grounded alternatives, choose separately for each model and modality, and freeze before the all-105 evaluation.</p>'+t('Draft thinking goals; no evaluation question or answer is supplied.',['ID','Goal','Work requested'],[[x['id'],e(x['name']),e(x['goal'])] for x in prompts['families']])+'<p>'+e(prompts['selection'])+'</p><details><summary>Draft instructions, outputs and controls</summary><p>'+e(prompts['shared_instruction'])+'</p><p><strong>For text:</strong> '+e(prompts['text_rule'])+'</p><p><strong>For audio:</strong> '+e(prompts['audio_rule'])+'</p><p><strong>Shared final-answer instruction:</strong> '+e(prompts['final_answer_instruction'])+'</p><p>'+e(prompts['prior_results_format'])+'</p><p>Combined-goal notes can contain facts, person/task links, checked implications, open items and source references; the summary control remains a summary rather than being forced into all these jobs.</p>'+ul(prompts['ablations'])+'<p>The main four-family comparison tests the whole amortized thinking method; a goal-only-at-request control separates improved prompting from reuse of earlier work. An example useful result is that B owns a promised consultation with Melissa and Jean, while the rule remains unresolved; another is a conditional 4:2:1 priority ratio from two twice-as-important relations.</p></details></section>'
 body+='<section class="section" id="metrics"><h2>Accuracy and thinking tokens for the request</h2>'+ul(p['metrics'])
 body+=t('Scoring and token-count symbols; all token counts use the indicated model’s tokenizer.',['Symbol','Meaning'],[[m(x['tex']),e(x['name']+'. '+x['definition'])] for x in notation['symbols'] if x['id'] in ['answer_asr','tokenizer','think_tokens','answer_tokens','control_tokens','amortized_tokens','request_out_tokens','request_in_tokens','helper_tokens','reference','facts','score','accuracy']])
 body+=eq(r'\mathrm{Acc}_{105}=\frac{1}{105}\sum_{e=1}^{105}a_e')
 body+=eq(r'N_e^{\mathrm{think}}=|\operatorname{Tok}_m(h_e)|')
 body+=eq(r'N_e^{\mathrm{am}}=\sum_{i:t_i<S_e}|\operatorname{Tok}_m(z_i)|')
 body+=eq(r'N_e^{\mathrm{req,out}}=N_e^{\mathrm{think}}+N_e^{\mathrm{ans}}+N_e^{\mathrm{aux}}+N_e^{\mathrm{ctrl}}')
 body+='<p>Use recorded generated token IDs; flag retokenized counts as approximate. The token sum applies when a native thinking channel is observable; otherwise its numerical value is N/A and the recorded total output count is reported directly. Earlier results read at request time are input tokens, even when they contain old reasoning. Acoustic codes and S1 Inner Monologue text are not relabeled as native thinking tokens.</p><p>Use paired outcomes and per-meeting summaries. Include partial-fact precision/recall and unsupported claims as diagnostics; compare request-time token reductions at comparable accuracy, with tokenizer and truncation status visible.</p></section>'
 body+='<section class="section" id="capacity"><h2>Retain full history, then use a declared fallback</h2>'+ul(p['capacity'])+'<p>Here '+m('B')+' is the model input budget after reserving output space; '+m(r'\mathcal S_B')+' is the fixed history-selection rule; '+m('D_e^B')+' and '+m('Z_e^B')+' are the history and earlier results it retains.</p>'+eq(r'(D_e^{B},Z_e^{B})=\mathcal S_B(D_e,Z_e^{-})')+'<p>Use the selected conditioning variables in a budgeted row; keep its mode distinct from full history and native rolling context.</p><p>The latest question is about 47.06 minutes into its source recording, so advertised short-clip support cannot establish full-prefix capacity. A fallback can be useful, but it must remain visible as a budgeted-history condition.</p></section>'
 body+='<section class="section" id="results"><h2>Results to fill after the plan is agreed</h2><p><strong>No new results are entered.</strong> The selected matrix has '+str(results['planned_cells'])+' cells × 105 questions = '+str(results['planned_final_responses'])+' planned final answers; this excludes earlier model calls, reference work, prompt search, judges and optional controls. Four text families become six cells per model because T3/T4 each use two transcript tools; the selected goal is frozen on separate development meetings.</p>'
 for group,label in [('S1','S1-only'),('text','Text-only S2'),('speech','Speech-LLM S2')]:
  rr=[x for x in results['rows'] if x['group']==group]
  body+=t(label+' result template. Dashes are unfilled measurements, not zero scores.',['Model','Family / tool','Planned questions','Correct / 105','Request thinking tokens','Request output tokens','Amortized thinking tokens','Context mode'],[[e(x['model']),x['family']+(' / '+x['tool'] if x['tool'] not in ['none','GT'] else '')+(' / selected goal' if x['method']=='amortized_thinking' else ''),'105','—','N/A: no native channel' if x['thinking_observability'].startswith('not_applicable') else '—','—','—','To record'] for x in rr])
 body+='<p><a href="research/what-to-think/results-template.csv">CSV template</a> · <a href="research/what-to-think/results-template.json">JSON template</a></p></section>'
 body+='<section class="section" id="appendix"><h2>Appendix</h2><details id="resources"><summary>Resource plan and execution order</summary><p>'+e(p['resources']['current_dependencies'])+' Current GPU count and maximum active GPU count are both zero.</p>'+t('Future GPU allocations, not measured capacity results; TP2 means splitting one model across two GPUs. Jobs are sequential; maximum four GPUs active.',['Job / stage','GPU count, type and VRAM','Roles, sharing and dependencies'],[[e(x['name']),e(x['resources'].split(';')[0]),e(x['resources']+' Qualify inputs and reference facts before evaluation.')] for x in registry['models']]+[[x['id']+' transcript tool','1 L40S 48 GB',e(x['resources']+' Run before T3/T4; outputs are reused across models.') ] for x in registry['transcript_tools']]+[['Reference proposal / validation','1 or 2 H100 80 GB','Qwen draft/check worker alone on GPU 0 or independent Gemma review TP2 on GPUs 0–1, sequential; Codex source inspection uses zero GPUs.'],['Answer judging','1 or 2 H100 80 GB','Use a different family where possible; judge alone on GPU 0 or TP2 across 0–1 after answer generation.']])+ul(p['resources'][key] for key in ['policy','qualification'])+'<ol>'+''.join('<li>'+e(x)+'</li>' for x in p['execution_order'])+'</ol></details><details id="literature"><summary>Verified papers and why they matter</summary>'+t('Primary-source literature; proposed thresholds and new evaluation results are not established by these papers.',['Paper','Relevant method','Use here'],[['<a href="'+x['url']+'">'+e(x['title'])+'</a><p>'+e(x['authors']+', '+str(x['year']))+'</p>',e(x['method']),e(x['relevance'])] for x in lit['papers']])+'</details><p><a href="research/what-to-think/plan.json">Plan data</a> · <a href="research/what-to-think/prompts.json">Draft prompt families</a> · <a href="research/what-to-think/models.json">Candidate registry</a> · <a href="research/what-to-think/literature.json">Checked sources</a> · <a href="research/what-to-think/manifest.json">File hashes</a></p></section>'
 finish('what-to-think.html','What to think: experiment plan',body)
 nt=Tables();body='<header class="hero"><h1>Notation table</h1></header><section class="section"><ul><li>Use these symbols consistently in the plan, prompts and future result files.</li><li>Keep native audio frames, larger thinking chunks, user requests and reasoning results separate.</li></ul><p><a href="what-to-think.html">Experiment plan</a> · <a href="todo.html">Project TODO</a> · <a href="research/what-to-think/notation.json">Registry JSON</a></p>'+nt('Notation version '+notation['version']+', maintained with the experiment plan.',['Symbol','Name','Definition'],[[m(x['tex']),e(x['name']),e(x['definition'])] for x in notation['symbols']],extra='notation-table')+'</section>'
 finish('notation.html','Notation table',body)
 build_progress(progress,p)
 print('Rendered what-to-think plan and maintained notation page; all result cells remain empty.')
if __name__=='__main__':main()
